package org.novasos.healthysv2.appointment;
import static org.assertj.core.api.Assertions.*;import java.time.Instant;import java.util.UUID;import org.junit.jupiter.api.Test;
class AppointmentTests{
 @Test void createsReschedulesCancelsAndKeepsHistory(){Instant start=Instant.parse("2026-10-01T10:00:00Z");var a=Appointment.create(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),null,"consultation",start,start.plusSeconds(1800),"Check-up",UUID.randomUUID());a.addParticipant(UUID.randomUUID(),"PATIENT");a.reschedule(start.plusSeconds(3600),start.plusSeconds(5400),UUID.randomUUID(),"Doctor request");a.cancel(UUID.randomUUID(),"Patient request");assertThat(a.getStatus()).isEqualTo("CANCELLED");assertThat(a.getParticipants()).hasSize(1);assertThat(a.getHistory()).extracting(AppointmentStatusHistory::getNext).containsExactly("SCHEDULED","RESCHEDULED","CANCELLED");}
 @Test void rejectsInvalidTimesAndDuplicateParticipant(){Instant now=Instant.now();assertThatThrownBy(()->Appointment.create(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),null,"CONSULTATION",now,now,null,null)).isInstanceOf(IllegalArgumentException.class);var a=Appointment.create(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),null,"CONSULTATION",now,now.plusSeconds(60),null,null);UUID person=UUID.randomUUID();a.addParticipant(person,"PATIENT");assertThatThrownBy(()->a.addParticipant(person,"PATIENT")).isInstanceOf(IllegalArgumentException.class);}
 @Test void managesWaitingQueue(){Instant now=Instant.now();var a=Appointment.create(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),null,"CONSULTATION",now,now.plusSeconds(60),null,null);var q=a.checkIn("Q-1",UUID.randomUUID());q.call();q.complete();assertThat(q.getStatus()).isEqualTo("COMPLETED");assertThat(q.getCalledAt()).isNotNull();assertThat(q.getCompletedAt()).isNotNull();}
}
